INSERT INTO `adrs` (`id`, `title`, `adopted_at`, `body`, `updated_at`) VALUES
('0001-adopt-adrs', 'Adopt Architecture Decision Records (ADRs)', 1745539200000, '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"background-and-motivation"},"content":[{"type":"text","text":"Background and Motivation"}]},{"type":"paragraph","content":[{"type":"text","text":"We want to set stricter boundaries for ourselves and make all technology choices transparent to the public, hence we''re establishing the format of ADRs."}]},{"type":"heading","attrs":{"level":2,"id":"goals-and-non-goals"},"content":[{"type":"text","text":"Goals and Non-Goals"}]},{"type":"heading","attrs":{"level":3,"id":"goals"},"content":[{"type":"text","text":"Goals"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Comprehensible"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"We accept and implement the decision made in the ADRs"}]}]}]},{"type":"heading","attrs":{"level":3,"id":"non-goals"},"content":[{"type":"text","text":"Non-Goals"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Be set in stone forever, new ADRs can supersede older ones"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"detailed-design"},"content":[{"type":"text","text":"Detailed Design"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"We''re using "},{"type":"text","text":"Google Design Docs","marks":[{"type":"link","attrs":{"href":"https://medium.com/@alessandro.traversi/mastering-google-design-docs-a-comprehensive-guide-with-readme-md-template-a2706b57f64d","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" as a loose template."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ADRs live inside "},{"type":"text","text":"content/adrs","marks":[{"type":"link","attrs":{"href":"https://github.com/rawkode-academy/rawkode-academy/tree/main/content/adrs/","target":null,"rel":null,"class":null,"title":null}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ADRs are named "},{"type":"text","text":"<zero-lead-four-digit-prefix>-<some-nice-file-name>.<md|mdx>","marks":[{"type":"code"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"As long as an ADR only contains a "},{"type":"text","text":"createdAt","marks":[{"type":"code"}]},{"type":"text","text":" date it''s in the state of "},{"type":"text","text":"Proposed","marks":[{"type":"code"}]},{"type":"text","text":", as soon as the ADR contains a "},{"type":"text","text":"adoptedAt","marks":[{"type":"code"}]},{"type":"text","text":" date it transitions in to the state "},{"type":"text","text":"Adopted","marks":[{"type":"code"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everyone can open an ADR via pull request. A constructive discussion in the pull request decides whether the ADR gets adopted or not"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"conclusion"},"content":[{"type":"text","text":"Conclusion"}]},{"type":"paragraph","content":[{"type":"text","text":"The concept of ADR will help us to focus on the real problems and prevents us to switch technologies too often."}]}]}', 1790105224000),
('0002-adopt-bun', 'Adopt Bun + Biome for JS/TS Services', 1746748800000, '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"context"},"content":[{"type":"text","text":"Context"}]},{"type":"paragraph","content":[{"type":"text","text":"Currently, Rawkode Academy utilizes Deno and Bun for its JavaScript/TypeScript services. While Deno has served its purpose, several factors have led us to reconsider this choice and aim for a single runtime:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sustainability Concerns:","marks":[{"type":"bold"}]},{"type":"text","text":" We have more confidence in the long-term sustainability and development trajectory of Bun compared to Deno."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deno Deploy Issues:","marks":[{"type":"bold"}]},{"type":"text","text":" We have encountered operational issues with Deno Deploy."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Lack of Transparency:","marks":[{"type":"bold"}]},{"type":"text","text":" The Deno team''s roadmap has not been consistently transparent, and their responsiveness to GitHub issues has been lacking."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This ADR proposes migrating to Bun as the primary JavaScript/TypeScript runtime and Biome as the linter/formatter."}]},{"type":"paragraph","content":[{"type":"text","text":"Bun","marks":[{"type":"bold"}]},{"type":"text","text":" offers several advantages:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Performance:","marks":[{"type":"bold"}]},{"type":"text","text":" Bun is designed for speed, offering faster startup times and execution."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Compatibility:","marks":[{"type":"bold"}]},{"type":"text","text":" It aims for broad Node.js compatibility, which can ease migration and integration with existing tools."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"All-in-one Toolkit:","marks":[{"type":"bold"}]},{"type":"text","text":" Bun includes a test runner, bundler, and package manager, potentially simplifying our development toolchain."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Biome","marks":[{"type":"bold"}]},{"type":"text","text":" provides:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Integrated Tooling:","marks":[{"type":"bold"}]},{"type":"text","text":" It combines linting, formatting, and other development tools into a single, cohesive package."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Performance:","marks":[{"type":"bold"}]},{"type":"text","text":" Biome is also built with performance in mind."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Opinionated Defaults:","marks":[{"type":"bold"}]},{"type":"text","text":" While configurable, Biome''s strong defaults can help maintain code consistency across projects."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"goals--non-goals"},"content":[{"type":"text","text":"Goals / Non-Goals"}]},{"type":"heading","attrs":{"level":3,"id":"goals"},"content":[{"type":"text","text":"Goals"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Standardize on a single, modern JavaScript/TypeScript runtime (Bun) for all services."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Adopt a unified, performant linting and formatting tool (Biome)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Improve developer experience through faster tooling and a simplified toolchain."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enhance long-term maintainability and confidence in our core JavaScript/TypeScript stack."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reduce operational friction encountered with previous solutions (e.g., Deno Deploy)."}]}]}]},{"type":"heading","attrs":{"level":3,"id":"non-goals"},"content":[{"type":"text","text":"Non-Goals"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Achieving 100% feature parity with Deno if it compromises the adoption of Bun''s strengths."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Immediately migrating all existing services in a \"big bang\" approach (a phased approach is preferred)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Replacing other established backend languages or runtimes used within Rawkode Academy (e.g., Go, Rust) where they are a better fit. This ADR is specific to JS/TS services."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Exhaustively evaluating every possible JS/TS runtime and tooling combination. The focus is on the identified benefits of Bun and Biome."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"decision"},"content":[{"type":"text","text":"Decision"}]},{"type":"paragraph","content":[{"type":"text","text":"We will adopt Bun as the standard runtime for all new and existing JavaScript/TypeScript services within Rawkode Academy. We will adopt Biome as the standard linter and formatter for all JavaScript/TypeScript projects."}]},{"type":"paragraph","content":[{"type":"text","text":"A phased migration plan will be developed for existing services currently running on Deno. New services should be initiated using Bun and Biome from the outset."}]},{"type":"heading","attrs":{"level":2,"id":"consequences"},"content":[{"type":"text","text":"Consequences"}]},{"type":"heading","attrs":{"level":3,"id":"positive"},"content":[{"type":"text","text":"Positive"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Improved Performance:","marks":[{"type":"bold"}]},{"type":"text","text":" Potentially faster build times, test execution, and application performance."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Simplified Tooling:","marks":[{"type":"bold"}]},{"type":"text","text":" Bun''s built-in features and Biome''s integrated nature may reduce the number of discrete development tools we need to manage."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Increased Developer Confidence:","marks":[{"type":"bold"}]},{"type":"text","text":" Aligning with a project (Bun) that we perceive as having a more robust and transparent future."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Enhanced Code Quality and Consistency:","marks":[{"type":"bold"}]},{"type":"text","text":" Biome''s strong linting and formatting capabilities will help maintain high standards."}]}]}]},{"type":"heading","attrs":{"level":3,"id":"negative"},"content":[{"type":"text","text":"Negative"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Migration Effort:","marks":[{"type":"bold"}]},{"type":"text","text":" Existing Deno services will require time and effort to migrate to Bun. This includes adapting code, build scripts, and deployment processes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Learning Curve:","marks":[{"type":"bold"}]},{"type":"text","text":" Developers will need to familiarize themselves with Bun and Biome, although the transition from Deno/other JS tools should be relatively smooth."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ecosystem Maturity:","marks":[{"type":"bold"}]},{"type":"text","text":" While Bun is rapidly developing, its ecosystem might not be as mature as Node.js in all areas. This could present challenges for specific libraries or integrations. Biome is also a newer tool compared to established linters/formatters like ESLint and Prettier."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Potential Unknowns:","marks":[{"type":"bold"}]},{"type":"text","text":" As with any technology shift, there may be unforeseen challenges or incompatibilities that arise during implementation."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"alternatives-considered"},"content":[{"type":"text","text":"Alternatives Considered"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sticking with Deno:","marks":[{"type":"bold"}]},{"type":"text","text":" This was rejected due to the concerns outlined in the Context section (sustainability, Deno Deploy issues, lack of transparency)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Migrating to Node.js with ESLint/Prettier:","marks":[{"type":"bold"}]},{"type":"text","text":" While Node.js is a mature and stable platform, Bun offers potential performance benefits and a more integrated toolchain. Biome also offers a more unified approach compared to managing ESLint and Prettier separately."}]}]}]}]}', 1764608082000);
INSERT INTO `adr_authors` (`adr_id`, `person_id`, `position`) VALUES
('0001-adopt-adrs', 'icepuma', 0),
('0001-adopt-adrs', 'rawkode', 1),
('0002-adopt-bun', 'rawkode', 0);
